using Content.Shared.Guidebook;
using Robust.Shared.GameStates;

namespace Content.Shared.Doors.Components;

/// <summary>
/// Companion component to <see cref="DoorComponent"/> that handles firelock-specific behavior, including
/// auto-closing on depressurization, air/fire alarm interactions, and preventing normal door functions when
/// retaining pressure..
/// </summary>
[RegisterComponent, NetworkedComponent, AutoGenerateComponentState]
public sealed partial class FirelockComponent : Component
{
    #region Settings

    /// <summary>
    /// Pry time modifier to be used when the firelock is currently closed due to fire or pressure.
    /// </summary>
    [DataField]
    public float LockedPryTimeModifier = 1.5f;

    /// <summary>
    /// Maximum pressure difference before the firelock will refuse to open, in kPa.
    /// </summary>
    [DataField, GuidebookData]
    public float PressureThreshold = 20;

    /// <summary>
    /// Maximum temperature difference before the firelock will refuse to open, in k.
    /// </summary>
    [DataField, GuidebookData]
    public float TemperatureThreshold = 230;
    // this used to check for hot-spots, but because accessing that data is a a mess this now just checks
    // temperature. This does mean a cold room will trigger hot-air pop-ups

    /// <summary>
    /// If true, and if this door has an <see cref="AtmosAlarmableComponent"/>, then it will only auto-close if the
    /// alarm is set to danger.
    /// </summary>
    [DataField]
    public bool AlarmAutoClose = true;

    /// <summary>
    /// The cooldown duration before a firelock can automatically close due to a hazardous environment after it has
    /// been pried open. Measured in seconds.
    /// </summary>
    [DataField]
    public TimeSpan EmergencyCloseCooldownDuration = TimeSpan.FromSeconds(2);

    #endregion

    #region Set by system

    /// <summary>
    /// When the firelock will be allowed to automatically close again due to a hazardous environment.
    /// </summary>
    [DataField]
    public TimeSpan? EmergencyCloseCooldown;

    /// <summary>
    /// Whether the firelock can open, or is locked due to its environment.
    /// </summary>
    public bool IsLocked => Pressure || Temperature;

    /// <summary>
    /// Whether the firelock is holding back a hazardous pressure.
    /// </summary>
    [DataField, AutoNetworkedField]
    public bool Pressure;

    /// <summary>
    /// Whether the firelock is holding back extreme temperatures.
    /// </summary>
    [DataField, AutoNetworkedField]
    public bool Temperature;

    /// <summary>
    /// Whether the airlock is powered.
    /// </summary>
    [DataField, AutoNetworkedField]
    public bool Powered;

    #endregion

    #region Client animation

    /// <summary>
    /// The sprite state used to animate the airlock frame when the airlock opens.
    /// </summary>
    [DataField]
    public string? OpeningLightSpriteState = "opening_unlit";

    /// <summary>
    /// The sprite state used to animate the airlock frame when the airlock closes.
    /// </summary>
    [DataField]
    public string? ClosingLightSpriteState = "closing_unlit";

    /// <summary>
    /// Whether or not the maintenance panel on this door should be animated.
    /// </summary>
    [DataField]
    public bool AnimatePanel = true;

    /// <summary>
    /// The sprite state used to animate the airlock panel when the airlock opens.
    /// </summary>
    [DataField]
    public string? OpeningPanelSpriteState = "panel_opening";

    /// <summary>
    /// The sprite state used to draw when the door is closed, but the panel is open.
    /// </summary>
    [DataField]
    public string? OpenPanelSpriteState = "panel_open";

    /// <summary>
    /// The sprite state used to animate the airlock panel when the airlock closes.
    /// </summary>
    [DataField]
    public string? ClosingPanelSpriteState = "panel_closing";

    /// <summary>
    /// The sprite state used for the closed airlock lights.
    /// </summary>
    [DataField]
    public string? WarningLightSpriteState = "closed_unlit";

    /// <summary>
    /// The sprite state used for the 'access denied' lights animation.
    /// </summary>
    [DataField]
    public string? DenySpriteState = "deny_unlit";

    #endregion
}
using Content.Shared.Doors.Components;
using Content.Shared.Doors.Systems;
using Content.Shared.SprayPainter.Prototypes;
using Robust.Client.Animations;
using Robust.Client.GameObjects;

namespace Content.Client.Doors;

/// <inheritdoc/>
public sealed partial class DoorSystem : SharedDoorSystem
{
    [Dependency] private AnimationPlayerSystem _animationSystem = default!;
    [Dependency] private SpriteSystem _sprite = default!;

    /// <inheritdoc/>
    protected override void OnComponentInit(Entity<DoorComponent> ent, ref ComponentInit args)
    {
        // Base call deferred until end of function.
        var comp = ent.Comp;
        comp.OpenSpriteStates = new(2);
        comp.ClosedSpriteStates = new(2);

        comp.OpenSpriteStates.Add((DoorVisualLayers.Base, comp.OpenSpriteState));
        comp.ClosedSpriteStates.Add((DoorVisualLayers.Base, comp.ClosedSpriteState));

        comp.OpeningAnimation = new Animation
        {
            Length = comp.OpeningAnimationTime,
            AnimationTracks =
            {
                new AnimationTrackSpriteFlick
                {
                    LayerKey = DoorVisualLayers.Base,
                    KeyFrames =
                    {
                        new AnimationTrackSpriteFlick.KeyFrame(comp.OpeningSpriteState, 0f),
                    },
                },
            },
        };

        comp.ClosingAnimation = new Animation
        {
            Length = comp.ClosingAnimationTime,
            AnimationTracks =
            {
                new AnimationTrackSpriteFlick
                {
                    LayerKey = DoorVisualLayers.Base,
                    KeyFrames =
                    {
                        new AnimationTrackSpriteFlick.KeyFrame(comp.ClosingSpriteState, 0f),
                    },
                },
            },
        };

        comp.EmaggingAnimation = new Animation
        {
            Length = comp.EmaggingAnimationTime,
            AnimationTracks =
            {
                new AnimationTrackSpriteFlick
                {
                    LayerKey = DoorVisualLayers.BaseEmagging,
                    KeyFrames =
                    {
                        new AnimationTrackSpriteFlick.KeyFrame(comp.EmaggingSpriteState, 0f),
                    },
                },
            },
        };

        base.OnComponentInit(ent, ref args);
    }

    [SubscribeLocalEvent]
    private void OnAnimationCompleted(Entity<DoorComponent> ent, ref AnimationCompletedEvent args)
    {
        if (args.Key != DoorComponent.OpenKey && args.Key != DoorComponent.CloseKey)
            return;

        if (!TryComp<SpriteComponent>(ent, out var sprite))
            return;

        switch (ent.Comp.State)
        {
            case DoorState.Open:

                foreach (var (layer, layerState) in ent.Comp.OpenSpriteStates)
                {
                    _sprite.LayerSetRsiState((ent.Owner, sprite), layer, layerState);
                }

                break;
            case DoorState.Closed:

                foreach (var (layer, layerState) in ent.Comp.ClosedSpriteStates)
                {
                    _sprite.LayerSetRsiState((ent.Owner, sprite), layer, layerState);
                }

                break;
        }
    }

    [SubscribeLocalEvent]
    private void OnAppearanceChange(Entity<DoorComponent> entity, ref AppearanceChangeEvent args)
    {
        if (args.Sprite == null)
            return;

        if (!args.TryGetData<DoorState>(DoorVisuals.State, out var state))
            state = DoorState.Closed;

        if (args.TryGetData<string>(PaintableVisuals.Prototype, out var prototype))
            UpdateSpriteLayers((entity.Owner, args.Sprite), prototype);

        if (_sprite.LayerMapTryGet(entity.Owner, DoorVisualLayers.BaseEmagging, out var emaggingLayer, logMissing: false))
            _sprite.LayerSetVisible(entity.Owner, emaggingLayer, state == DoorState.Emagging);

        UpdateAppearanceForDoorState(entity, args.Sprite, state);
    }

    private void UpdateAppearanceForDoorState(Entity<DoorComponent> entity, SpriteComponent sprite, DoorState state)
    {
        _sprite.SetDrawDepth((entity.Owner, sprite), state is DoorState.Open ? entity.Comp.OpenDrawDepth : entity.Comp.ClosedDrawDepth);

        switch (state)
        {
            case DoorState.Open:
                if (_animationSystem.HasRunningAnimation(entity, DoorComponent.OpenKey))
                    return;

                if (_animationSystem.HasRunningAnimation(entity, DoorComponent.CloseKey))
                {
                    _animationSystem.Stop(entity, null, DoorComponent.CloseKey);
                    _animationSystem.Play(entity, (Animation)entity.Comp.OpeningAnimation, DoorComponent.OpenKey);
                }

                foreach (var (layer, layerState) in entity.Comp.OpenSpriteStates)
                {
                    // Allow animations to play while it's open (e.g., pinion);
                    // the animation unsets this so we gotta set it again.
